(()=>{
const reduce=matchMedia('(prefers-reduced-motion: reduce)');
const hero=document.querySelector('.hero-board'),story=document.querySelector('.canvas-workflow'),workspace=document.querySelector('.workflow-board'),steps=[...document.querySelectorAll('[data-step]')];
let heroTime=0,last=0,frame=0,heroVisible=true;
function phase(board,value){if(board.dataset.phase===String(value))return;board.dataset.phase=value;board.querySelector('.zoom-label').textContent=value===3?'40%':'68%';board.querySelectorAll('video').forEach(v=>{if(value>=1&&!reduce.matches)v.play().catch(()=>{});else v.pause()})}
function tick(now){const dt=last?Math.min((now-last)/1000,.1):0;last=now;if(heroVisible&&!document.hidden)heroTime+=dt;const t=heroTime%14;phase(hero,t<1?0:t<4?1:t<9?2:3);frame=requestAnimationFrame(tick)}
if(hero){if(reduce.matches)phase(hero,3);else frame=requestAnimationFrame(tick);}
if(hero)new IntersectionObserver(([e])=>{heroVisible=e.isIntersecting;if(!heroVisible)hero.querySelector('video').pause()},{threshold:.05}).observe(hero);
function updateStory(){if(!story||!workspace)return;const r=story.getBoundingClientRect(),length=story.offsetHeight-innerHeight,p=Math.max(0,Math.min(1,-r.top/Math.max(1,length)));const stage=p<.33?0:p<.68?1:2;steps.forEach((b,i)=>{b.classList.toggle('active',i===stage);b.setAttribute('aria-pressed',i===stage)});phase(workspace,stage+1)}
let queued=false;addEventListener('scroll',()=>{if(!queued){queued=true;requestAnimationFrame(()=>{queued=false;updateStory()})}},{passive:true});addEventListener('resize',updateStory);steps.forEach((b,i)=>b.addEventListener('click',()=>{const y=scrollY+story.getBoundingClientRect().top;scrollTo({top:y+(story.offsetHeight-innerHeight)*[.08,.48,.84][i],behavior:reduce.matches?'instant':'smooth'})}));updateStory();
document.querySelectorAll('.download-demo').forEach(button=>button.addEventListener('click',()=>{const b=button.closest('.workspace'),notice=b.querySelector('.canvas-notice');phase(b,3);notice.textContent='Your sample asset is ready';notice.classList.add('visible');const a=document.createElement('a');a.href='assets/canvas/product-board.jpg';a.download='runable-canvas-reference.jpg';a.click();setTimeout(()=>notice.classList.remove('visible'),2500)}));
document.querySelectorAll('.canvas-feature').forEach(card=>{let timer;function play(){if(reduce.matches)return;clearTimeout(timer);card.classList.remove('playing');void card.offsetWidth;card.classList.add('playing');const video=card.querySelector('video');if(video){video.currentTime=0;video.play().catch(()=>{})}const text=card.querySelector('[data-original]');if(text){text.textContent=text.dataset.original;setTimeout(()=>{text.textContent=text.dataset.new},1700)}timer=setTimeout(()=>{card.classList.remove('playing');if(video)video.pause()},4500)}card.addEventListener('pointerenter',e=>{if(e.pointerType!=='touch')play()});card.addEventListener('focus',play);card.addEventListener('pointerup',e=>{if(e.pointerType==='touch')play()});card.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();play()}})});
if(!reduce.matches){const targets=document.querySelectorAll('.canvas-section-head>* ,.canvas-feature,.faq h2,.faq details,#pricing>h2,.price-plan,.billing-toggle,.closing-cta>h2,.closing-cta>p,.closing-cta>a,.footer-directory>div');const observer=new IntersectionObserver(entries=>{entries.forEach((e,i)=>{if(e.isIntersecting){e.target.style.transitionDelay=Math.min(i*70,280)+'ms';e.target.classList.add('visible');observer.unobserve(e.target)}})},{threshold:.08});targets.forEach(e=>{e.classList.add('canvas-reveal');observer.observe(e)});document.addEventListener('focusin',e=>e.target.closest('.canvas-reveal')?.classList.add('visible'))}
reduce.addEventListener('change',()=>{cancelAnimationFrame(frame);if(reduce.matches){if(hero)phase(hero,3);document.querySelectorAll('video').forEach(v=>v.pause());document.querySelectorAll('.canvas-reveal').forEach(e=>e.classList.add('visible'))}else if(hero){last=0;frame=requestAnimationFrame(tick)}});
})();
